@Component("diagnosis-handler")
@ProcessingGroup("diagnosis-processing-group")
public class DiagnosisEventHandler {
	
	// core constructor
	DiagnosisEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDiagnosisEvent
     */
    @EventHandler
    public void handle( CreateDiagnosisEvent event) {
        entityManager.persist(new Diagnosis(event.getDiagnosisId(), event.getCode(), event.getDescription(), event.getOnsetDate(), event.getEncounter(), event.getPatient(), event.getCertainty()));
    }

    /*
     * @param	event UpdateDiagnosisEvent
     */
    @EventHandler
    public Diagnosis handle( UpdateDiagnosisEvent event) {
    	entityManager.merge(new Diagnosis(event.getDiagnosisId(), event.getCode(), event.getDescription(), event.getOnsetDate(), event.getEncounter(), event.getPatient(), event.getCertainty()));
    }
    
    /*
     * @param	event DeleteDiagnosisEvent
     */
    @EventHandler
    public void on( DeleteDiagnosisEvent event) {
    	Diagnosis entity = new Diagnosis();
   
    	// ------------------------------------------
    	// apply the DiagnosisId
    	// ------------------------------------------
    	entity.setDiagnosisId( event.getDiagnosisId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DiagnosisRepository diagnosisEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DiagnosisEventHandler.class.getName());

}
